const openEditModal = (pet) => {
  setEditingPet(pet._id);
  setEditPet({
    name: pet.name || '',
    species: pet.species || '',
    breed: pet.breed || '',
    age: pet.age || '',
    ageUnit: pet.ageUnit || 'Years',
    weight: pet.weight || '',
    weightUnit: pet.weightUnit || 'kg',
    gender: pet.gender || 'Male',
    color: pet.color || '',
    image: pet.image || '',
    description: pet.description || '',
    vaccinated: pet.vaccinated !== undefined ? pet.vaccinated : true,
    healthStatus: pet.healthStatus || 'Healthy'
  });
  document.getElementById('editPetModal').classList.remove('hidden');
};

const handleUpdatePet = async (e) => {
  e.preventDefault();
  setUpdatingPet(true);

  try {
    const payload = { 
      name: editPet.name,
      species: editPet.species,
      breed: editPet.breed,
      age: editPet.age ? Number(editPet.age) : 1,
      ageUnit: editPet.ageUnit,
      weight: editPet.weight ? Number(editPet.weight) : 5,
      weightUnit: editPet.weightUnit,
      gender: editPet.gender,
      color: editPet.color,
      image: editPet.image,
      description: editPet.description,
      vaccinated: editPet.vaccinated,
      healthStatus: editPet.healthStatus,
      ownerId: user.id || user._id 
    };

    const token = localStorage.getItem('userToken') || '';

    const res = await fetch(`${import.meta.env.VITE_API_URL}/api/pets/${editingPet}`, {
      method: 'PUT',
      headers: { 
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${token}`
      },
      body: JSON.stringify(payload)
    });
    const data = await res.json();

    if (res.ok && data.success) {
      // Replace the pet in the list with the DB-returned data
      setPets(prev => prev.map(p => p._id === editingPet ? data.data : p));
      // Update favorite pet image if this was the favorite
      if (localStorage.getItem('favoritePetId') === editingPet) {
        localStorage.setItem('favoritePetImage', data.data.image || '');
        window.dispatchEvent(new Event('favoritePetChanged'));
      }
      setEditingPet(null);
      setEditPet(null);
      document.getElementById('editPetModal').classList.add('hidden');
    } else {
      alert(data.message || 'Failed to update pet');
    }
  } catch (err) {
    alert("Error updating pet: " + err.message);
  } finally {
    setUpdatingPet(false);
  }
};

